        count = 0
        for i in range(n):
            for j in range(i+1, n):
                for k in range(j+1, n):
                    if f[i] + f[j] == f[k]:
                        count += 1
        return count

    def additive_energy(f):
        n = int(math.log2(len(f)))
        return additivity(f) / (n * (n - 1) * (n - 2))

    def acc0_circuit_size_bound(n, epsilon):
