    for i in range(n):
        for j in range(1 << i):
            for k in range(1 << (n - i)):
                M_P[j][j ^ k] += 1
                M_P[j ^ k][j] += 1
    M_P = gaussian_elimination(M_P)

    norm_M_P = spectral_norm(M_P)

    # Construct transition matrix for IP_2 function
