                    i_max = i
                    break
            if i_max == -1:
                continue
            M[rank], M[i_max] = M[i_max], M[rank]
            rank += 1
            for i in range(rank, m):
                factor = M[i][j] / M[rank-1][j]
                for k in range(n):
                    M[i][k] -= factor * M[rank-1][k]
        return rank

    return gaussian_elimination(M)

