    det = 0
    for j in range(n):
        submatrix = [[matrix[i][k] for k in range(j) + range(j+1, n)] for i in range(1, n)]
        det += ((-1) ** j) * matrix[0][j] * determinant(n - 1, submatrix)
    return det

