def fast_walsh_hadamard_transform(f: list) -> list:
    n = len(f)
    while n > 1:
        half = n // 2
        for i in range(half):
            for j in range(i, n, n):
                u = f[j]
                v = f[j + half]
                f[j] = u + v
                f[j + half] = (u - v) * math.sqrt(2)
        n //= 2
    return f

