    random.seed(seed)

    def sign(x):
        return 1 if x >= 0 else -1

    def binomial(n, k):
        if k > n:
            return 0
        result = 1
        for i in range(k):
            result *= (n - i)
            result //= (i + 1)
        return result

    def kronecker_coefficient(λ, μ, ν):
        if len(λ) != len(μ) or len(μ) != len(ν):
            return 0
        n = len(λ)
        coeff = Fraction(1)
        for i in range(n):
            coeff *= binomial(λ[i] + μ[i], λ[i]) * binomial(μ[i] + ν[i], μ[i])
            coeff //= (binomial(λ[i] + ν[i], λ[i]) * binomial(ν[i] + λ[i], ν[i]))
        return abs(coeff)

