import random
import math

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    def generate_primes(limit):
        primes = []
        for num in range(2, limit):
            if is_prime(num):
                primes.append(num)
        return primes

    def generate_random_3sat_instance(n):
        clauses = []
        for _ in range(3 * n):
            clause = [random.choice([-1, 1]) * random.randint(1, n) for _ in range(3)]
            if len(set(clause)) == 3:
                clauses.append(clause)
        return clauses

    def gf2_polynomial_from_3sat(clauses):
        n = max(abs(var) for clause in clauses for var in clause)
        poly = [0] * (1 << n)
        for clause in clauses:
            product = 1
            for var in clause:
                if var > 0:
                    product ^= 1 << (var - 1)
                else:
                    product ^= 1 << (-var - 1)
            poly[product] += 1
        return poly

    def factorize_poly(poly):
        n = len(poly)
        factors = []
        for i in range(1, n):
            if poly[i] != 0 and all(poly[j] % poly[i] == 0 for j in range(i + 1, n)):
                factors.append([i])
                break
        return factors

    def count_irreducible_components(poly):
        return len(factorize_poly(poly))

    def acc0_circuit_size_estimate(n):
        return 2 ** (n // 2)

    n = random.choice([5, 10, 15, 20, 30, 40])
    instance = generate_random_3sat_instance(n)
    poly = gf2_polynomial_from_3sat(instance)
    irreducible_components_count = count_irreducible_components(poly)
    acc0_size_estimate = acc0_circuit_size_estimate(n)

    return {
        "metric_name": "irreducible_components_count",
        "metric_value": irreducible_components_count,
        "instances_tested": 1,
        "conjecture_holds": irreducible_components_count >= acc0_size_estimate,
        "counterexample": "" if irreducible_components_count >= acc0_size_estimate else f"n={n}, poly={poly}"
    }

if __name__ == "__main__":
    import sys
    seeds = [int(x) for x in sys.argv[1:]] or generate_primes(100)[:30]

    results = []
    for seed in seeds:
        result = run_trial(seed)
        print(f"TRIAL: {result}")
        results.append(result)

    mean_value = sum(r["metric_value"] for r in results) / len(results)
    std_value = math.sqrt(sum((r["metric_value"] - mean_value) ** 2 for r in results) / len(results))
    support_fraction = sum(1 for r in results if r["conjecture_holds"]) / len(results)

    if all(r["conjecture_holds"] for r in results):
        print(f"RESULT: SUPPORTED mean={mean_value:.2f} std={std_value:.2f} support_fraction={support_fraction:.2f}")
    elif any(not r["conjecture_holds"] for r in results):
        first_failing_seed = next(seed for seed, result in zip(seeds, results) if not result["conjecture_holds"])
        print(f"RESULT: FALSIFIED counterexample=\"{result['counterexample']}\" first_failing_seed={first_failing_seed}")
    else:
        print("RESULT: INCONCLUSIVE mapping_undefined")

import random
import math

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def free_cumulant(truth_table):
        n = len(truth_table)
        cumulants = [0] * (n + 1)
        for i in range(n):
            for j in range(i, n):
                if truth_table[i][j]:
                    cumulants[j - i + 1] += 1
        return max(cumulants)

    def moment_cumulant_inversion(moments):
        cumulants = [0] * len(moments)
        for k in range(1, len(moments)):
            cumulants[k] = moments[k]
            for j in range(k - 1, 0, -1):
                cumulants[j] -= (j + 1) * cumulants[j + 1]
            cumulants[0] /= k
        return cumulants

    def generate_3sat_instance(n):
        instance = []
        for _ in range(2**n):
            assignment = [random.choice([True, False]) for _ in range(n)]
            clause = random.choice([assignment, [not x for x in assignment]])
            instance.append(clause)
        return instance

    def truth_table(instance):
        n = len(instance[0])
        table = [[False] * (2**n) for _ in range(2**n)]
        for i in range(2**n):
            assignment = [bool(i >> j & 1) for j in range(n)]
            for clause in instance:
                if all([assignment[j] or not x for j, x in enumerate(clause)]):
                    table[i][i ^ sum(1 << j for j, x in enumerate(assignment))] = True
        return table

    def read_twice_bp(truth_table):
        n = len(truth_table)
        bp = [[False] * (2**n) for _ in range(2**n)]
        for i in range(n):
            for j in range(2**n):
                if truth_table[i][j]:
                    bp[j][j ^ 1 << i] = True
        return bp

    def cumulants(bp):
        n = len(bp)
        moments = [0] * (n + 1)
        for i in range(n):
            for j in range(i, n):
                if bp[i][j]:
                    moments[j - i + 1] += 1
        return moment_cumulant_inversion(moments)

    def ip2_function():
        bp = [[False] * (2**40) for _ in range(2**40)]
        for i in range(2**40):
            for j in range(i, 2**40):
                if i & j == 0:
                    bp[i][j] = True
        return bp

    n = 40
    instance = generate_3sat_instance(n)
    truth_table_3sat = truth_table(instance)
    cumulant_3sat = free_cumulant(truth_table_3sat)

    ip2_bp = ip2_function()
    cumulants_ip2 = cumulants(ip2_bp)

    max_cumulant_3sat = max(cumulant_3sat)
    max_cumulant_ip2 = max(cumulants_ip2)

    conjecture_holds = max_cumulant_3sat <= 5 * math.log(n) and max_cumulant_ip2 > 40
    counterexample = "" if conjecture_holds else "mapping_undefined"

    return {
        "metric_name": "max_free_cumulant",
        "metric_value": max_cumulant_3sat,
        "instances_tested": 1,
        "conjecture_holds": conjecture_holds,
        "counterexample": counterexample
    }

if __name__ == "__main__":
    import sys
    seeds = [int(s) for s in sys.argv[1:]] or [2**i - 1 for i in range(5, 30)]

    results = []
    for seed in seeds:
        result = run_trial(seed)
        print(f"TRIAL: {result}")
        results.append(result)

    mean_value = sum(r["metric_value"] for r in results) / len(results)
    std_value = math.sqrt(sum((r["metric_value"] - mean_value)**2 for r in results) / len(results))
    support_fraction = sum(1 for r in results if r["conjecture_holds"]) / len(results)

    if all(r["conjecture_holds"] for r in results):
        print(f"RESULT: SUPPORTED mean={mean_value} std={std_value} support_fraction={support_fraction}")
    elif any(not r["conjecture_holds"] for r in results):
