                return False
        return True

    def generate_sipser_like_cnf(n):
        clauses = set()
        for i in range(2**(n//2)):
            clause = []
            for j in range(n):
                if (i >> j) & 1:
                    clause.append(random.choice([j, -j]))
            clauses.add(tuple(sorted(clause)))
        return clauses

